import{_ as t,a as o}from"./chunks/source_control.BN-IASeV.js";import{_ as i}from"./chunks/code_hosting.D407rqvg.js";import{_ as s}from"./chunks/launchers.DMrfRju-.js";import{_ as a,o as r,c as n,ae as h}from"./chunks/framework.sRTLHEzD.js";const l="/heidrun_code/screenshots/features/clipboard.png",q=JSON.parse('{"title":"The sidebar sections","description":"The File explorer, Source control, Code hosting, Launchers, and Clipboard sidebar sections keep the project tools next to your coding agents.","frontmatter":{"description":"The File explorer, Source control, Code hosting, Launchers, and Clipboard sidebar sections keep the project tools next to your coding agents."},"headers":[],"relativePath":"features/sidebar_sections.md","filePath":"features/sidebar_sections.md"}'),c={name:"features/sidebar_sections.md"};function d(u,e,p,f,b,m){return r(),n("div",null,[...e[0]||(e[0]=[h('<h1 id="the-sidebar-sections" tabindex="-1">The sidebar sections <a class="header-anchor" href="#the-sidebar-sections" aria-label="Permalink to &quot;The sidebar sections&quot;">​</a></h1><p>Around your coding agents, you need more: the files of the project, the Git changes, the issues, the commands of the project, and the pieces of text that you want to keep. Without Heidrun Code, each one is in a different application.</p><h2 id="what-heidrun-code-does" tabindex="-1">What Heidrun Code does <a class="header-anchor" href="#what-heidrun-code-does" aria-label="Permalink to &quot;What Heidrun Code does&quot;">​</a></h2><p>The left sidebar and the right sidebar each hold several sidebar sections. The sidebar icon bar, at the outer edge of each sidebar, shows one icon for each sidebar section. Click an icon to show its sidebar section.</p><h2 id="file-explorer-sidebar-section" tabindex="-1">File explorer sidebar section <a class="header-anchor" href="#file-explorer-sidebar-section" aria-label="Permalink to &quot;File explorer sidebar section&quot;">​</a></h2><p>The File explorer sidebar section, in the left sidebar, shows the whole folder tree of the Git repository of the selected workspace.</p><ul><li>Click a folder to fold it or to unfold it.</li><li>Click a file to open it in a pane next to your terminal. Type in the pane to change the file, and press ⌘S to save it.</li><li>Select lines in that pane, then click &quot;Explain&quot; or &quot;Fix these lines&quot;: the prompt goes to the coding agent of the same tab.</li><li>The option &quot;Ignored files&quot; of its menu shows or hides the files that Git ignores.</li><li>Press ⌘P to find a file of the project by a part of its name.</li></ul><p><img src="'+t+'" alt="The File explorer sidebar section with the folders and the files at the root of the repository." width="300"></p><h2 id="search-in-files-sidebar-section" tabindex="-1">Search in files sidebar section <a class="header-anchor" href="#search-in-files-sidebar-section" aria-label="Permalink to &quot;Search in files sidebar section&quot;">​</a></h2><p>The Search in files sidebar section, in the left sidebar, searches a text in all the files of the Git repository of the selected workspace.</p><ul><li>Type the text, and choose &quot;Match case&quot; or &quot;Regular expression&quot; if you need them.</li><li>The results are grouped by file. Click a line to open the file at that line, in a pane next to your terminal.</li></ul><h2 id="source-control-sidebar-section" tabindex="-1">Source control sidebar section <a class="header-anchor" href="#source-control-sidebar-section" aria-label="Permalink to &quot;Source control sidebar section&quot;">​</a></h2><p>The Source control sidebar section, in the left sidebar, shows the Git changes of the selected workspace, as the source control view of Visual Studio Code does.</p><ul><li>Stage the files, write the commit message, and press ⌘Enter to commit.</li><li>The menu of the commit button also gives &quot;Commit and push&quot;, and &quot;Commit (amend the last commit)&quot;.</li><li>The sparkle button asks a coding agent to write the commit message from the diff. See <a href="/heidrun_code/features/ai.html">The use of AI</a>.</li><li>A click on a changed file shows its diff in a pane next to your terminal, read only, as a diff or side by side.</li></ul><p><img src="'+o+'" alt="The Source control sidebar section with the commit message box, the commit button, and the list of the changed files." width="300"></p><h2 id="code-hosting-sidebar-section" tabindex="-1">Code hosting sidebar section <a class="header-anchor" href="#code-hosting-sidebar-section" aria-label="Permalink to &quot;Code hosting sidebar section&quot;">​</a></h2><p>The Code hosting sidebar section, in the left sidebar, shows the open issues and the open pull requests of GitHub, or the merge requests of GitLab, for the repository of the selected workspace.</p><ul><li>Click a row to read more about the issue or the pull request in an information card.</li><li>Type in the search field to find an item, and save a search that you use often.</li></ul><p><img src="'+i+'" alt="The Code hosting sidebar section with the search field and the list of the open issues of the repository." width="300"></p><h2 id="launchers-sidebar-section" tabindex="-1">Launchers sidebar section <a class="header-anchor" href="#launchers-sidebar-section" aria-label="Permalink to &quot;Launchers sidebar section&quot;">​</a></h2><p>The Launchers sidebar section, in the left sidebar, lists the launchers of the selected workspace. A launcher is a name, a command line, and an optional folder.</p><ul><li>Click &quot;Run&quot; to run the command line of a launcher in its own tab.</li><li>Import launchers from the scripts of the file <code>package.json</code> in one click.</li><li>Create a custom launcher that runs a command line, or a coding agent with a prompt.</li></ul><p>A launcher has one of two levels. Choose the level when you create a custom launcher, and change it later when you edit the custom launcher.</p><ul><li>A launcher of the workspace level shows only in its workspace. Heidrun Code saves it in the file <code>.heidrun/config.json</code> of the repository, so your team shares it.</li><li>A launcher of the user level shows in every workspace. Heidrun Code saves it in the file <code>launchers.json</code> in its data folder on your computer, so it is not shared. Its folder, when it has one, is read from the root of each workspace.</li></ul><p><img src="'+s+'" alt="The Launchers sidebar section with five launchers, each with its description and its button Run." width="300"></p><h2 id="clipboard-sidebar-section" tabindex="-1">Clipboard sidebar section <a class="header-anchor" href="#clipboard-sidebar-section" aria-label="Permalink to &quot;Clipboard sidebar section&quot;">​</a></h2><p>The Clipboard sidebar section, in the right sidebar, lists the notes that you pinned from the text of a terminal. Find a command, an error, or an answer again later. The switch &quot;All workspaces&quot; shows the notes of every workspace.</p><p><img src="'+l+'" alt="The Clipboard sidebar section with two notes pinned from the text of two terminals, each with its buttons Copy and Send to." width="300"></p><p><em>A Viking keeps the axe, the shield, and the horn of mead within reach. You keep your files, your branches, and your issues within reach.</em></p>',29)])])}const y=a(c,[["render",d]]);export{q as __pageData,y as default};
